function validate([s1, s2]) {
  if (typeof s1 !== 'string' || s1.length < 1 || s1.length > 20000) return 's1 needs 1 to 20000 characters.';
  if (typeof s2 !== 'string' || s2.length < 1 || s2.length > 100) return 's2 needs 1 to 100 characters.';
  if (!/^[a-z]+$/.test(s1) || !/^[a-z]+$/.test(s2)) return 'Both strings use only lowercase English letters.';
  return null;
}

