function minWindow(s1, s2) {
  const m = s2.length;
  const dp = new Array(m).fill(-1);
  let bestStart = -1;
  let bestLength = Infinity;

  for (let i = 0; i < s1.length; i++) {
    for (let j = m - 1; j >= 1; j--) {
      if (s1[i] === s2[j]) {
        dp[j] = dp[j - 1];
      }
    }
    if (s1[i] === s2[0]) {
      dp[0] = i;
    }
    const start = dp[m - 1];
    if (start !== -1 && i - start + 1 < bestLength) {
      bestStart = start;
      bestLength = i - start + 1;
    }
  }
  return bestStart === -1 ? "" : s1.slice(bestStart, bestStart + bestLength);
}

