function minWindow(s1, s2) {
  const holds = (part) => {
    let k = 0;
    for (const ch of part) if (k < s2.length && ch === s2[k]) k++;
    return k === s2.length;
  };
  for (let len = 1; len <= s1.length; len++)
    for (let from = 0; from + len <= s1.length; from++)
      if (holds(s1.slice(from, from + len))) return s1.slice(from, from + len);
  return "";
}

