function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = (n, k) => Array.from({ length: n }, () => letters[pick(k)]).join('');
  if (size === 'large') {
    const k = 2 + pick(4);
    const s1 = word(10000, k);
    const s2 = word(60 + pick(41), k);
    return [s1, s2];
  }
  const k = 1 + pick(3);
  return [word(1 + pick(12), k), word(1 + pick(4), k)];
}
